PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_total NUMBER;
BEGIN
    -- on failure we used to: RAISE; or call log_pkg.write(SQLERRM);
    UPDATE @@tab@@
       SET @@col@@ = SYSDATE
     WHERE id = p_id;
    l_total := SQL%ROWCOUNT;
    @@proc2@@(l_total);
EXCEPTION
    /* handler for everything else */
    WHEN /* any error */ OTHERS THEN -- @expect
        -- RAISE;
        /* log_pkg.write(SQLERRM); */
        NULL;
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_skipped PLS_INTEGER := 0;
BEGIN
    <<outer>>
    FOR i IN 1 .. p_ids.COUNT LOOP
        BEGIN
            BEGIN
                @@proc2@@(p_ids(i));
            EXCEPTION
                WHEN OTHERS THEN -- @expect
                    l_skipped := l_skipped + 1;
            END;
            @@proc2@@(p_ids(i) + 1);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END LOOP outer;
    DBMS_OUTPUT.PUT_LINE('skipped ' || l_skipped);
EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END @@proc@@;

FUNCTION @@proc@@ (p_text IN VARCHAR2) RETURN NUMBER IS
    l_result NUMBER;

    PROCEDURE note (p_msg IN VARCHAR2) IS
    BEGIN
        DBMS_OUTPUT.PUT_LINE(p_msg);
    EXCEPTION
        WHEN OTHERS THEN
            log_pkg.write(p_msg, SQLCODE);
    END note;
BEGIN
    note('start');
    l_result := TO_NUMBER(p_text);
    note('converted');
    RETURN l_result;
EXCEPTION
    WHEN OTHERS THEN -- @expect
        RETURN -1;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_template VARCHAR2(200);
BEGIN
    l_template := q'[BEGIN do_it; EXCEPTION WHEN OTHERS THEN NULL; END;]';
    @@proc2@@(l_template, p_id);
    UPDATE @@tab@@
       SET @@col@@ = 'DONE'
     WHERE id = p_id;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        @@proc2@@('no data', p_id);
    WHEN OTHERS THEN -- @expect
        ROLLBACK;
END @@proc@@;

FUNCTION @@proc@@ (p_val IN NUMBER) RETURN NUMBER IS
    l_out NUMBER;
BEGIN
    BEGIN
        l_out := 100 / p_val;
    EXCEPTION
        WHEN ZERO_DIVIDE THEN
            app_log.write('division by zero');
            RAISE;
    END;
    RETURN l_out;
EXCEPTION
    WHEN   OTHERS -- @expect
        THEN
        app_log.write('failed');
        RETURN NULL;
END @@proc@@;

