PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_text VARCHAR2(200) := q'[EXCEPTION WHEN OTHERS THEN NULL;]';
BEGIN
    -- WHEN OTHERS THEN NULL;
    /* EXCEPTION
           WHEN OTHERS THEN NULL;  */
    UPDATE @@tab@@
       SET @@col@@ = l_text
     WHERE id = p_id;
EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
        NULL;
    WHEN NO_DATA_FOUND THEN
        RETURN;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_msg VARCHAR2(400);
BEGIN
    <<outer>>
    BEGIN
        <<middle>>
        DECLARE
            l_n NUMBER;
        BEGIN
            l_n := p_id * 2;
            @@proc2@@(l_n);
        EXCEPTION
            WHEN OTHERS THEN
                RAISE_APPLICATION_ERROR(-20100, 'inner failure', TRUE);
        END middle;
    EXCEPTION
        WHEN OTHERS THEN
            l_msg := SQLERRM;
            @@proc2@@(l_msg);
            RAISE;
    END outer;
END @@proc@@;

FUNCTION @@proc@@ (p_code IN VARCHAR2) RETURN NUMBER IS
    l_val NUMBER;

    FUNCTION to_num (p_in IN VARCHAR2) RETURN NUMBER IS
    BEGIN
        RETURN TO_NUMBER(p_in);
    EXCEPTION
        WHEN OTHERS THEN
            RAISE;
    END to_num;
BEGIN
    l_val := to_num(p_code);
    RETURN l_val;
EXCEPTION
    WHEN OTHERS THEN
        Pkg_Util.LOG_ERROR('conversion failed', p_code);
        RETURN NULL;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
BEGIN
    $IF $$debug_mode $THEN
        DBMS_OUTPUT.PUT_LINE('start ' || p_id);
    $END
    @@proc2@@(p_id);
EXCEPTION
    WHEN OTHERS THEN
        $IF $$debug_mode $THEN
            DBMS_OUTPUT.PUT_LINE('failed');
        $END
        RAISE;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_status OUT VARCHAR2) IS
BEGIN
    @@proc2@@(p_id);
    p_status := 'OK';
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        p_status := 'MISSING';
    WHEN OTHERS THEN
        p_status := CASE
                        WHEN p_id > 0 THEN DBMS_UTILITY.
                            FORMAT_ERROR_STACK
                        ELSE 'unknown'
                    END;
END @@proc@@;
